{
  "metrics": [],
  "businessConcepts": [
    {
      "id": "eec8559b-a615-4a6a-93aa-9399a95ebafa",
      "name": "Account type",
      "description": "We categorize merchants into different account types based on their business model and industry classification: R Enterprise - Retail, D Enterprise - Digital, H Enterprise - Hospitality, F Platform - Franchise, S Platform - SaaS, O Other."
    },
    {
      "id": "81fb44ad-0f08-4a3b-80f1-21105ab48a0d",
      "name": "Authorization Characteristics Indicator (ACI)",
      "description": "Identifies the transaction flow submitted to the acquirer. A Card present - Non-authenticated, B Card Present - Authenticated, C Tokenized card with mobile device, D Card Not Present - Card On File, E Card Not Present - Recurring Bill Payment, F Card Not Present - 3-D Secure, G Card Not Present - Non-3-D Secure."
    },
    {
      "id": "4c34c506-0f73-499e-842f-cac24b7b37cc",
      "name": "Capture delay",
      "description": "The number of days in which the capture from authorization to settlement needs to happen. Possible values are '3-5' (between 3 and 5 days), '>5' (more than 5 days is possible), '<3' (before 3 days), 'immediate', or 'manual'. The faster the capture to settlement happens, the more expensive it is."
    },
    {
      "id": "be38efd8-44c8-40b5-8840-d8aa69b813ba",
      "name": "Fee rule null means all values",
      "description": "If a field is set to null it means that it applies to all possible values of that field. E.g. null value in aci means that the rules applies for all possible values of aci."
    },
    {
      "id": "0e61118c-5758-4764-9a01-95279d76bd02",
      "name": "Intracountry (local acquiring)",
      "description": "A transaction is domestic (intracountry) when the issuer country and the acquiring country are the same. Local acquiring refers to the scenario where the issuer country is the same as the acquirer country. International transactions, where the issuer country and acquirer country are different, typically are more expensive."
    },
    {
      "id": "d243b3ba-79cf-4a8a-9771-3b7c268e05f9",
      "name": "Monthly volume and monthly fraud level",
      "description": "Monthly volumes and rates are computed always in natural months (e.g. January, February), starting always in day 1 and ending in the last natural day of the month (i.e. 28 for February, 30 or 31). Fraud is defined as the ratio of fraudulent volume over total volume. monthly_volume is the monthly total volume of the merchant in euros; '100k-1m' is between 100.000 (100k) and 1.000.000 (1m)."
    },
    {
      "id": "10e5b2fc-e0ae-41c0-87bb-77ca7855e7fd",
      "name": "Payment processing fee",
      "description": "fee = fixed_amount + rate * transaction_value / 10000. Fixed amount and transaction values are given in the same currency, typically euros. Payment Processing Fees depend on a number of characteristics. These characteristics belong to either the merchant or the transaction. The full list of fee rules is the fees table."
    }
  ],
